import{_ as t,o as a,c as o,ag as i}from"./chunks/framework.DXGyWiRo.js";const h=JSON.parse('{"title":"Outage Remediation Skill","description":"","frontmatter":{},"headers":[],"relativePath":"skills/outage-remediation.md","filePath":"skills/outage-remediation.md"}'),s={name:"skills/outage-remediation.md"};function n(r,e,d,l,c,u){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="outage-remediation-skill" tabindex="-1">Outage Remediation Skill <a class="header-anchor" href="#outage-remediation-skill" aria-label="Permalink to &quot;Outage Remediation Skill&quot;">​</a></h1><p>The Outage Remediation Skill helps with post-outage recovery by analyzing active incidents, generating remediation plans, and recommending preventive measures.</p><h2 id="capability" tabindex="-1">Capability <a class="header-anchor" href="#capability" aria-label="Permalink to &quot;Capability&quot;">​</a></h2><ul><li>Detects active Azure Service Health incidents</li><li>Generates remediation plans for specific incidents by tracking ID</li><li>Creates comprehensive post-outage action plans combining incident data with reliability recommendations</li></ul><h2 id="skill-configuration" tabindex="-1">Skill Configuration <a class="header-anchor" href="#skill-configuration" aria-label="Permalink to &quot;Skill Configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>Skill Name</td><td><code>OutageRemediationSkill</code></td></tr><tr><td>Model</td><td><code>gpt-4o</code></td></tr><tr><td>Temperature</td><td><code>0.0</code></td></tr><tr><td>Timeout</td><td><code>120s</code></td></tr></tbody></table><h2 id="system-prompt-summary" tabindex="-1">System Prompt Summary <a class="header-anchor" href="#system-prompt-summary" aria-label="Permalink to &quot;System Prompt Summary&quot;">​</a></h2><p>The LLM is instructed to cover:</p><ul><li>Monitoring and alerting improvements</li><li>BCDR (Business Continuity and Disaster Recovery) enhancements</li><li>Chaos engineering recommendations</li><li>Operational process improvements</li></ul><h2 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>OutageRemediationTools-GetActiveIncidents</code></td><td><code>GetActiveIncidents(subscriptionIds)</code></td><td>Queries Service Health for <code>ServiceIssue</code> events in the last 30 days</td></tr><tr><td><code>OutageRemediationTools-GetRemediationPlan</code></td><td><code>GetRemediationPlan(subscriptionIds, trackingId)</code></td><td>Retrieves root cause and remediation guidance for a specific incident by tracking ID</td></tr><tr><td><code>OutageRemediationTools-GetPostOutageActionPlan</code></td><td><code>GetPostOutageActionPlan(subscriptionIds)</code></td><td>Combines Service Health events (30 days) with Advisor HA recommendations into a single dataset for the LLM to synthesize</td></tr><tr><td><code>SubscriptionTools-ListResourceGroups</code></td><td><code>ListResourceGroups(subscriptionId)</code></td><td>Lists resource groups for scoping</td></tr><tr><td><code>ResourceGraphTools-QueryResources</code></td><td><code>QueryResources(subscriptionIds, resourceType?)</code></td><td>General resource lookup</td></tr></tbody></table><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Azure Service Health</span></span>
<span class="line"><span>    └─ servicehealthresources</span></span>
<span class="line"><span>    └─ type == &quot;microsoft.resourcehealth/events&quot;</span></span>
<span class="line"><span>    └─ eventType == &quot;ServiceIssue&quot;</span></span>
<span class="line"><span>    └─ 30-day lookback window</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Azure Advisor Recommendations</span></span>
<span class="line"><span>    └─ advisorresources | category == &quot;HighAvailability&quot;</span></span>
<span class="line"><span>    └─ Used for gap analysis in post-outage action plans</span></span></code></pre></div><h2 id="how-post-outage-plans-work" tabindex="-1">How Post-Outage Plans Work <a class="header-anchor" href="#how-post-outage-plans-work" aria-label="Permalink to &quot;How Post-Outage Plans Work&quot;">​</a></h2><p>The <code>GetPostOutageActionPlan</code> tool combines two data sources in a single response:</p><ol><li><strong>Recent incidents</strong> — Service Health <code>ServiceIssue</code> events from the last 30 days</li><li><strong>HA recommendations</strong> — Advisor <code>HighAvailability</code> recommendations for the same subscriptions</li></ol><p>The LLM then:</p><ul><li>Correlates which recommendations could have prevented or mitigated past incidents</li><li>Identifies gaps in monitoring, redundancy, and disaster recovery</li><li>Generates a prioritized action plan covering immediate, short-term, and long-term improvements</li></ul><h2 id="example-query" tabindex="-1">Example Query <a class="header-anchor" href="#example-query" aria-label="Permalink to &quot;Example Query&quot;">​</a></h2><blockquote><p>&quot;We had an outage last week. What should we do to prevent it from happening again?&quot;</p></blockquote><p><strong>Tool Calls:</strong></p><ol><li><code>OutageRemediationTools-GetActiveIncidents([&quot;sub-prod&quot;])</code> → recent Service Health incidents</li><li><code>OutageRemediationTools-GetPostOutageActionPlan([&quot;sub-prod&quot;])</code> → combined incident + HA data</li><li><code>ResourceGraphTools-QueryResources([&quot;sub-prod&quot;])</code> → affected resource inventory</li></ol><p><strong>Output:</strong> Structured markdown with incident summary, root cause analysis, and multi-phase remediation plan.</p>`,23)])])}const m=t(s,[["render",n]]);export{h as __pageData,m as default};
